import 'dart:convert';
import 'dart:typed_data';

/// Same playable MP4 bytes used by U1 (`app_ui_flow.dart`).
const playableMp4Base64 =
    '';

const _minValidMp4Bytes = 64 * 1024;

Uint8List playableMp4Bytes() {
  final base = Uint8List.fromList(base64Decode(playableMp4Base64));
  if (base.length >= _minValidMp4Bytes) {
    return base;
  }
  final padded = Uint8List(_minValidMp4Bytes);
  padded.setRange(0, base.length, base);
  return padded;
}
